class Solution {
  private long[] pre;
  private long[] prev, cur;

  private long tri(long s) {
    return s * (s + 1) / 2;
  }

  private void solve(int lo, int hi, int optLo, int optHi) {
    if (lo > hi) return;
    int mid = (lo + hi) >>> 1;
    long best = Long.MAX_VALUE;
    int bestK = optLo;
    for (int t = optLo; t <= Math.min(mid - 1, optHi); t++) {
      if (prev[t] == Long.MAX_VALUE) continue;
      long v = prev[t] + tri(pre[mid] - pre[t]);
      if (v < best) {
        best = v;
        bestK = t;
      }
    }
    cur[mid] = best;
    solve(lo, mid - 1, optLo, bestK);
    solve(mid + 1, hi, bestK, optHi);
  }

  public long minPartitionScore(int[] nums, int k) {
    int n = nums.length;
    pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
    prev = new long[n + 1];
    java.util.Arrays.fill(prev, Long.MAX_VALUE);
    prev[0] = 0;
    for (int j = 1; j <= k; j++) {
      cur = new long[n + 1];
      java.util.Arrays.fill(cur, Long.MAX_VALUE);
      solve(j, n, j - 1, n - 1);
      prev = cur;
    }
    return prev[n];
  }
}
